<?php $data = json_decode(file_get_contents("php://input"), true); $conn = new mysqli("localhost", "root", "", "traccar"); foreach ($data as $item) { $stmt = $conn->prepare("INSERT INTO tc_contas_pagar (descricao, valor, vencimento, pago) VALUES (?, ?, ?, 0)"); $stmt->bind_param("sds", $item["descricao"], $item["valor"], $item["vencimento"]); $stmt->execute(); } echo json_encode(["success" => true]); ?>